{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Molecule 1 showed an absolute oral bioavailability of 15.5% after oral administration in 8 healthy subjects, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Molecule 2 had an estimated absolute bioavailability of about 10-15% for the oral ayahuasca exposure, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Molecule 8 showed an absolute bioavailability of 50.4 ± 6.2% after a 40-mg oral dose in healthy male subjects, above the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The most transferable direct absolute-bioavailability evidence is consistently below 20% (e.g., propafenone 15.5%, DMT 10-15%, sumatriptan 14%, epanolol ~7%, agomelatine <5%, eluxadoline 1%). Contradictory high values such as ketanserin ~50% and tadalafil 36-80% have lower assay-transfer scores or less direct absolute measurements, so the overall prediction is low.",
  "evidence_gaps": [
    "Tadalafil records conflict between 36% and ~80% and many are not absolute measurements, limiting their weight.",
    "Fluvastatin records include extended-release low values and immediate-release values around 19-30%, straddling the threshold.",
    "Some records were obtained under altered conditions such as rifampin induction or food and were discounted."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

